CREATE TABLE krrg_employee_development_direction (
id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
name VARCHAR(100) NOT NULL,
CONSTRAINT uk_krrg_employee_development_direction_name UNIQUE (name)
);

